def choose_architecture(task):
    if task.parallelizable or task.needs_distinct_roles:
        return "multi-agent"       # benefit justifies the overhead
    if task.is_single_pass:
        return "single-agent"      # crew would only add cost/latency
    return "single-agent"          # default to the cheaper option

# 'summarize this doc' -> single-agent
# 'research 5 sources then synthesize + critique' -> multi-agent

class Budget:
    def __init__(self, max_tokens, max_rounds, max_seconds):
        self.max_tokens = max_tokens
        self.max_rounds = max_rounds
        self.max_seconds = max_seconds
        self.tokens = 0

    def check(self, round_no, elapsed):
        if self.tokens > self.max_tokens: raise RuntimeError("token budget hit")
        if round_no >= self.max_rounds:   raise RuntimeError("round cap hit")
        if elapsed > self.max_seconds:    raise RuntimeError("time budget hit")

# enforce before every turn so no single run can run away
budget = Budget(max_tokens=50_000, max_rounds=6, max_seconds=30)
